  1	import { readFile, readdir } from 'fs/promises';
  2	import { join } from 'path';
  3	import type { Dirent } from 'fs';
  4	import {
  5	  KnowledgeStoreSchema,
  6	  InsightSchema,
  7	  SLUG_REGEX,
  8	  type KnowledgeStore,
  9	  type Insight,
 10	  type InsightScope,
 11	} from '../schema/knowledge.js';
 12	import { atomicWriteJson } from './atomic-writer.js';
 13	import { withLock } from './file-lock.js';
 14	import { now } from '../utils/timestamp.js';
 15	
 16	/**
 17	 * Manages the `.knowledge/` directory, providing all CRUD operations for
 18	 * insights with atomic writes, file locking, and in-memory search/filter logic.
 19	 *
 20	 * Storage layout (relative to `ledgerRoot`):
 21	 *   .knowledge/
 22	 *     .lock                              — lock file created by withLock
 23	 *     global-insights.json              — insights with scope: 'global'
 24	 *     {repository_name}-insights.json   — insights scoped to a specific repository
 25	 *
 26	 * Locking strategy:
 27	 *   - All read-modify-write sequences (addInsight, updateInsight, deleteInsight)
 28	 *     acquire a single lock on knowledgeDir() for the entire operation.
 29	 *   - All writes use atomicWriteJson() — write-to-temp-then-rename.
 30	 *   - Pure reads (readGlobalStore, readRepositoryStore, searchInsights, listInsights)
 31	 *     do not acquire a lock, consistent with the LedgerStore pattern.
 32	 *
 33	 * scope === 'repository' + repository_name constraint:
 34	 *   The Zod schema accepts repository_name as optional to remain context-free.
 35	 *   This class enforces the constraint: addInsight() throws if scope is 'repository'
 36	 *   and repository_name is absent.
 37	 */
 38	export class KnowledgeStoreManager {
 39	  public readonly ledgerRoot: string;
 40	
 41	  constructor(ledgerRoot: string) {
 42	    this.ledgerRoot = ledgerRoot;
 43	  }
 44	
 45	  // ==================== Path Helpers ====================
 46	
 47	  knowledgeDir(): string {
 48	    return join(this.ledgerRoot, '.knowledge');
 49	  }
 50	
 51	  globalStorePath(): string {
 52	    return join(this.knowledgeDir(), 'global-insights.json');
 53	  }
 54	
 55	  /**
 56	   * Returns the file path for a repository-scoped insights store.
 57	   *
 58	   * @param repoName - Repository name (used to derive the filename)
 59	   * @throws Error if repoName is 'global' (reserved name)
 60	   * @throws Error if repoName contains unsafe characters (path traversal guard)
 61	   */
 62	  repositoryStorePath(repoName: string): string {
 63	    if (repoName === 'global') {
 64	      throw new Error("'global' is a reserved name and cannot be used as a repository name.");
 65	    }
 66	    this._validateSlug(repoName);
 67	    return join(this.knowledgeDir(), `${repoName}-insights.json`);
 68	  }
 69	
 70	  // ==================== Read Methods ====================
 71	
 72	  /**
 73	   * Reads and validates the global insights store.
 74	   * Returns a valid empty KnowledgeStore if the file does not yet exist.
 75	   *
 76	   * @throws Error if the file exists but contains malformed JSON or fails schema validation
 77	   */
 78	  async readGlobalStore(): Promise<KnowledgeStore> {
 79	    return this._readStore(this.globalStorePath());
 80	  }
 81	
 82	  /**
 83	   * Reads and validates a repository-scoped insights store.
 84	   * Returns a valid empty KnowledgeStore if the file does not yet exist.
 85	   *
 86	   * @param repoName - Repository name (used to derive the filename)
 87	   * @throws Error if the file exists but contains malformed JSON or fails schema validation
 88	   */
 89	  async readRepositoryStore(repoName: string): Promise<KnowledgeStore> {
 90	    return this._readStore(this.repositoryStorePath(repoName));
 91	  }
 92	
 93	  // ==================== Write Methods ====================
 94	
 95	  /**
 96	   * Writes the global insights store atomically under a lock.
 97	   * Validates the data against KnowledgeStoreSchema before writing.
 98	   *
 99	   * @param data - Store data to persist
100	   * @throws Error if validation fails or write fails

101	   * @warning Do NOT call this method from inside a withLock(knowledgeDir, ...) callback.
102	   *   The CRUD methods (addInsight, updateInsight, deleteInsight) intentionally bypass
103	   *   this method and call atomicWriteJson directly to avoid nested lock acquisition,
104	   *   which would deadlock. This method is safe only at the top level.
105	   */
106	  async writeGlobalStore(data: KnowledgeStore): Promise<void> {
107	    await withLock(this.knowledgeDir(), async () => {
108	      const validated = KnowledgeStoreSchema.parse(data);
109	      await atomicWriteJson(this.globalStorePath(), validated);
110	    });
111	  }
112	
113	  /**
114	   * Writes a repository-scoped insights store atomically under a lock.
115	   * Validates the data against KnowledgeStoreSchema before writing.
116	   *
117	   * @param repoName - Repository name
118	   * @param data - Store data to persist
119	   * @throws Error if validation fails or write fails
120	   * @warning Do NOT call this method from inside a withLock(knowledgeDir, ...) callback.
121	   *   The CRUD methods (addInsight, updateInsight, deleteInsight) intentionally bypass
122	   *   this method and call atomicWriteJson directly to avoid nested lock acquisition,
123	   *   which would deadlock. This method is safe only at the top level.
124	   */
125	  async writeRepositoryStore(repoName: string, data: KnowledgeStore): Promise<void> {
126	    await withLock(this.knowledgeDir(), async () => {
127	      const validated = KnowledgeStoreSchema.parse(data);
128	      await atomicWriteJson(this.repositoryStorePath(repoName), validated);
129	    });
130	  }
131	
132	  // ==================== ID Generation ====================
133	
134	  /**
135	   * Increments the store's next_id counter and returns the formatted ID string.
136	   *
137	   * Mutates the store object in-place — the updated store must be written to disk
138	   * for the counter to persist across process restarts.
139	   *
140	   * @param store - The store whose counter should be incremented
141	   * @returns Formatted ID string in KN-NNNN format (e.g., "KN-0001" for next_id=1)
142	   */
143	  nextId(store: KnowledgeStore): string {
144	    const id = store.next_id;
145	    store.next_id = id + 1;
146	    return `KN-${String(id).padStart(4, '0')}`;
147	  }
148	
149	  // ==================== CRUD Operations ====================
150	
151	  /**
152	   * Adds a new insight to the appropriate store (global or repository-scoped).
153	   *
154	   * Assigns the numeric id from the store's next_id counter and persists the
155	   * incremented counter. Enforces the repository_name requirement for
156	   * repository-scoped insights. The entire read-modify-write sequence runs
157	   * under a single lock.
158	   *
159	   * @param input - Insight data without the id field (auto-assigned from next_id)
160	   * @returns The created Insight with the assigned numeric id
161	   * @throws Error if scope === 'repository' and repository_name is absent
162	   */
163	  async addInsight(input: Omit<Insight, 'id'>): Promise<Insight> {
164	    if (input.scope === 'repository' && !input.repository_name) {
165	      throw new Error('repository_name is required for repository-scoped insights');
166	    }
167	
168	    return await withLock(this.knowledgeDir(), async () => {
169	      const storePath =
170	        input.scope === 'global'
171	          ? this.globalStorePath()
172	          : this.repositoryStorePath(input.repository_name!);
173	
174	      const store = await this._readStore(storePath);
175	
176	      // Save the numeric id before nextId increments the counter.
177	      // The KN-NNNN return value of nextId() is intentionally discarded here —
178	      // display-format IDs are produced by MCP tool layer consumers, not stored.
179	      const numericId = store.next_id;
180	      this.nextId(store);
181	
182	      const insight: Insight = InsightSchema.parse({ ...input, id: numericId });
183	      store.insights.push(insight);
184	      store.last_updated = now();
185	
186	      const validated = KnowledgeStoreSchema.parse(store);
187	      await atomicWriteJson(storePath, validated);
188	
189	      return insight;
190	    });
191	  }
192	
193	  /**
194	   * Searches insights across all (or filtered) stores for the query string.
195	   *
196	   * Applies a case-insensitive substring match against title, content, and every
197	   * entry in the tags array. Optionally narrows by tags (intersection), then
198	   * applies offset/limit pagination — in that order.
199	   *
200	   * @param query - Substring to search for (case-insensitive)
201	   * @param filters - Optional scope/category/repository_name filters to narrow the stores searched,
202	   *   plus optional tags (intersection filter), limit, and offset for pagination.
203	   *   - `filters.tags` — Case-sensitive intersection filter; every tag in this array must be
204	   *     present in `insight.tags` using exact-case matching. This contrasts with the
205	   *     case-insensitive text search applied to `query`. Pass tags in the exact casing
206	   *     they were stored with.
207	   * @returns Insights matching the query, filtered by tags, and paginated
208	   */
209	  async searchInsights(
210	    query: string,
211	    filters?: {
212	      scope?: InsightScope;
213	      repository_name?: string;
214	      category?: string;
215	      tags?: string[];
216	      limit?: number;
217	      offset?: number;
218	    }
219	  ): Promise<Insight[]> {
220	    const { tags: tagFilter, limit, offset = 0, ...loadFilters } = filters ?? {};
221	
222	    const allInsights = await this._loadInsights(loadFilters);
223	    const q = query.toLowerCase();
224	
225	    let results = allInsights.filter(
226	      (insight) =>
227	        insight.title.toLowerCase().includes(q) ||
228	        insight.content.toLowerCase().includes(q) ||
229	        insight.tags.some((tag) => tag.toLowerCase().includes(q))
230	    );
231	
232	    if (tagFilter && tagFilter.length > 0) {
233	      results = results.filter((insight) =>
234	        tagFilter.every((tag) => insight.tags.includes(tag))
235	      );
236	    }
237	
238	    return results.slice(offset, limit !== undefined ? offset + limit : undefined);
239	  }
240	
241	  /**
242	   * Lists insights with optional scope/category/tags/repository_name filters and pagination.
243	   *
244	   * Filters are applied in this order: store selection (scope/repository_name) → category →
245	   * tags → offset → limit.
246	   *
247	   * @param filters - Scope, category, tags, repository_name filters; limit and offset for pagination
248	   * @returns Filtered and paginated insight array
249	   */
250	  async listInsights(filters: {
251	    scope?: InsightScope;
252	    category?: string;
253	    tags?: string[];
254	    repository_name?: string;
255	    limit?: number;
256	    offset?: number;
257	  }): Promise<Insight[]> {
258	    const { limit, offset = 0, tags: tagFilter, ...loadFilters } = filters;
259	
260	    let insights = await this._loadInsights(loadFilters);
261	
262	    if (tagFilter && tagFilter.length > 0) {
263	      insights = insights.filter((insight) =>
264	        tagFilter.every((tag) => insight.tags.includes(tag))
265	      );
266	    }
267	
268	    return insights.slice(offset, limit !== undefined ? offset + limit : undefined);
269	  }
270	
271	  /**
272	   * Updates an existing insight by numeric ID.
273	   *
274	   * When `filter.scope` and/or `filter.repository_name` are provided the search is
275	   * restricted to the matching store(s), preventing accidental global-insight
276	   * mutation when the same numeric ID exists in multiple stores. Without a
277	   * filter, all stores are scanned (original behaviour — preserved for
278	   * backwards compatibility).
279	   *
280	   * Applies the provided partial updates and sets updated_at to the current
281	   * timestamp. The entire read-modify-write sequence runs under a single lock.
282	   *
283	   * Immutable fields (id, scope, repository_name, created_at) are not accepted
284	   * in the updates parameter.
285	   *
286	   * @param id - Numeric insight id
287	   * @param updates - Partial insight fields to update
288	   * @param filter - Optional scope/repository_name filter to restrict which store is searched
289	   * @returns The updated Insight
290	   * @throws Error if no insight with the given id exists in the filtered stores
291	   */
292	  async updateInsight(
293	    id: number,
294	    updates: Partial<
295	      Pick<Insight, 'title' | 'content' | 'category' | 'tags' | 'source' | 'confidence' | 'superseded_by'>
296	    >,
297	    filter?: { scope?: InsightScope; repository_name?: string }
298	  ): Promise<Insight> {
299	    return await withLock(this.knowledgeDir(), async () => {
300	      const storePaths = await this._storePathsForFilter(filter);

301	
302	      for (const storePath of storePaths) {
303	        const store = await this._readStore(storePath);
304	        const idx = store.insights.findIndex((i) => i.id === id);
305	
306	        if (idx === -1) continue;
307	
308	        const updatedInsight: Insight = InsightSchema.parse({
309	          ...store.insights[idx],
310	          ...updates,
311	          updated_at: now(),
312	        });
313	
314	        store.insights[idx] = updatedInsight;
315	        store.last_updated = now();
316	
317	        const validated = KnowledgeStoreSchema.parse(store);
318	        await atomicWriteJson(storePath, validated);
319	
320	        return updatedInsight;
321	      }
322	
323	      throw new Error(`Insight with id ${id} not found`);
324	    });
325	  }
326	
327	  /**
328	   * Moves an insight from one store to another in a single atomic lock span,
329	   * eliminating the TOCTOU window inherent in the previous add→delete two-step pattern.
330	   *
331	   * The operation performs these steps inside a single withLock(knowledgeDir) span:
332	   *   1. Resolve the source store path(s) from sourceFilter.
333	   *   2. Find the insight by id in the source store — throws if not found.
334	   *   3. Construct the moved insight: new id (from the target store's next_id counter),
335	   *      corrected scope/repository_name, and a fresh updated_at timestamp.
336	   *   4. Validate the new insight with InsightSchema.parse(…).
337	   *   5. Write the updated target store (with the new insight appended) via atomicWriteJson.
338	   *   6. Remove the original insight from the source store and write it via atomicWriteJson.
339	   *
340	   * @param id - Numeric id of the insight to move
341	   * @param sourceFilter - Scope (and optional repository_name) of the store containing the insight
342	   * @param targetScope - Destination scope ('global' or 'repository')
343	   * @param targetRepositoryName - Required when targetScope === 'repository'
344	   * @returns The moved Insight with new id, corrected scope/repository_name, and updated_at
345	   * @throws Error if the insight is not found in the source store(s)
346	   * @throws Error if targetScope === 'repository' and targetRepositoryName is absent
347	   * @throws Error if source and target resolve to the same store (identity move)
348	   * @warning Do NOT call from inside a withLock(knowledgeDir, …) callback.
349	   *   This method acquires the lock itself; a nested call would deadlock.
350	   */
351	  async moveInsight(
352	    id: number,
353	    sourceFilter: { scope: InsightScope; repository_name?: string },
354	    targetScope: InsightScope,
355	    targetRepositoryName?: string
356	  ): Promise<Insight> {
357	    if (targetScope === 'repository' && !targetRepositoryName) {
358	      throw new Error('targetRepositoryName is required when targetScope is "repository"');
359	    }
360	
361	    // Guard against identity moves: same repository → same repository
362	    if (
363	      sourceFilter.scope === 'repository' &&
364	      targetScope === 'repository' &&
365	      sourceFilter.repository_name !== undefined &&
366	      sourceFilter.repository_name === targetRepositoryName
367	    ) {
368	      throw new Error(
369	        `Cannot move insight to the same repository store: "${targetRepositoryName}"`
370	      );
371	    }
372	
373	    return await withLock(this.knowledgeDir(), async () => {
374	      // 1. Resolve source path(s)
375	      const sourcePaths = await this._storePathsForFilter(sourceFilter);
376	
377	      // 2. Find insight in source store
378	      let sourceStorePath: string | undefined;
379	      let sourceStore: KnowledgeStore | undefined;
380	      let sourceIdx = -1;
381	
382	      for (const storePath of sourcePaths) {
383	        const store = await this._readStore(storePath);
384	        const idx = store.insights.findIndex((i) => i.id === id);
385	        if (idx !== -1) {
386	          sourceStorePath = storePath;
387	          sourceStore = store;
388	          sourceIdx = idx;
389	          break;
390	        }
391	      }
392	
393	      if (!sourceStorePath || !sourceStore || sourceIdx === -1) {
394	        throw new Error(`Insight with id ${id} not found`);
395	      }
396	
397	      const originalInsight = sourceStore.insights[sourceIdx];
398	
399	      // 3. Resolve target store path and read it
400	      const targetStorePath =
401	        targetScope === 'global'
402	          ? this.globalStorePath()
403	          : this.repositoryStorePath(targetRepositoryName!);
404	
405	      const targetStore = await this._readStore(targetStorePath);
406	
407	      // 4. Construct the moved insight with new id, scope, and updated_at
